package inventory

import (
	"os"
	"path/filepath"
	"testing"
)

// writeThresholds 在临时工作目录里铺一份 inventory/thresholds.json，并把进程
// 工作目录切过去——阈值来源是相对进程工作目录解析的。content 为空表示不铺文件。
func writeThresholds(t *testing.T, content string) {
	t.Helper()
	dir := t.TempDir()
	if content != "" {
		if err := os.MkdirAll(filepath.Join(dir, "inventory"), 0o755); err != nil {
			t.Fatalf("建配置目录失败：%v", err)
		}
		path := filepath.Join(dir, "inventory", "thresholds.json")
		if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
			t.Fatalf("写配置失败：%v", err)
		}
	}
	t.Chdir(dir)
}

func TestLowStockThresholdPerWarehouse(t *testing.T) {
	writeThresholds(t, `{"shanghai": 20}`)

	if got := LowStockThreshold("shanghai"); got != 20 {
		t.Fatalf("LowStockThreshold(shanghai) = %d, 期望已配置的 20", got)
	}
	if got := LowStockThreshold("beijing"); got != DefaultLowStockThreshold {
		t.Fatalf("未配置仓库 LowStockThreshold(beijing) = %d, 期望默认值 %d",
			got, DefaultLowStockThreshold)
	}
}

func TestLowStockThresholdMissingConfigFallsBack(t *testing.T) {
	writeThresholds(t, "")

	if got := LowStockThreshold("shanghai"); got != DefaultLowStockThreshold {
		t.Fatalf("缺配置文件时 LowStockThreshold(shanghai) = %d, 期望默认值 %d",
			got, DefaultLowStockThreshold)
	}
}

func TestIsLowStockUsesConfiguredThreshold(t *testing.T) {
	writeThresholds(t, `{"shanghai": 20}`)

	if !IsLowStock("shanghai", 19) {
		t.Fatal("低于已配置阈值应当算低库存")
	}
	if IsLowStock("shanghai", 20) {
		t.Fatal("等于已配置阈值不算低库存（严格小于）")
	}
}

func TestLowStockWarehousesUsesConfiguredThresholds(t *testing.T) {
	writeThresholds(t, `{"shanghai": 20, "beijing": 3}`)

	got := LowStockWarehouses(map[string]int{"shanghai": 15, "beijing": 2, "chengdu": 5})
	want := []string{"beijing", "shanghai"}
	if len(got) != len(want) {
		t.Fatalf("LowStockWarehouses = %v, 期望 %v", got, want)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("LowStockWarehouses = %v, 期望 %v", got, want)
		}
	}
}

